#include <bits/stdc++.h>
using namespace std;
struct N {
    int l = 0, r = 0, s = 0;
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    for (int cs = 1; cs <= T; cs++) {
        int n, m;
        cin >> n >> m;
        vector<int> a(n), v;
        for (int& x : a) cin >> x;
        v = a;
        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());
        vector<N> tr(1);
        vector<int> rt(n + 1);
        function<int(int, int, int, int)> ins = [&](int p, int l, int r, int q) {
            int x = tr.size();
            tr.push_back(tr[p]);
            tr[x].s++;
            if (l < r) {
                int z = (l + r) / 2;
                if (q <= z)
                    tr[x].l = ins(tr[p].l, l, z, q);
                else
                    tr[x].r = ins(tr[p].r, z + 1, r, q);
            }
            return x;
        };
        for (int i = 1; i <= n; i++)
            rt[i] = ins(rt[i - 1], 0, (int)v.size() - 1,
                        lower_bound(v.begin(), v.end(), a[i - 1]) - v.begin());
        function<int(int, int, int, int)> qry = [&](int p, int l, int r, int q) {
            if (!p || q < l) return 0;
            if (r <= q) return tr[p].s;
            int z = (l + r) / 2;
            return qry(tr[p].l, l, z, q) + qry(tr[p].r, z + 1, r, q);
        };
        cout << "Case " << cs << ":\n";
        while (m--) {
            int l, r, h;
            cin >> l >> r >> h;
            int q = upper_bound(v.begin(), v.end(), h) - v.begin() - 1;
            cout << qry(rt[r + 1], 0, v.size() - 1, q) - qry(rt[l], 0, v.size() - 1, q) << "\n";
        }
    }
}

