#include <ext/pb_ds/assoc_container.hpp>
#include <ext/pb_ds/tree_policy.hpp>
using namespace std;
using namespace __gnu_pbds;
using OST = tree<pair<long long, int>, null_type, less<pair<long long, int>>, rb_tree_tag,
                 tree_order_statistics_node_update>;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long mn;
    if (!(cin >> n >> mn)) return 0;
    OST t;
    long long add = 0;
    int id = 0, left = 0;
    while (n--) {
        char op;
        long long x;
        cin >> op >> x;
        if (op == 'I') {
            if (x >= mn) t.insert({x - add, ++id});
        } else if (op == 'A')
            add += x;
        else if (op == 'S') {
            add -= x;
            long long cut = mn - add;
            int k = t.order_of_key({cut, INT_MIN});
            left += k;
            while (k--) t.erase(t.begin());
        } else {
            if (x > (long long)t.size())
                cout << -1 << "\n";
            else
                cout << t.find_by_order(t.size() - x)->first + add << "\n";
        }
    }
    cout << left << "\n";
}

