Mat operator*(const Mat& A, const Mat& B) {
    Mat C(A.n);
    for (int i = 0; i < A.n; i++)
        for (int k = 0; k < A.n; k++)
            if (A.a[i][k])
                for (int j = 0; j < A.n; j++) C.a[i][j] = (C.a[i][j] + A.a[i][k] * B.a[k][j]) % p;
