    vector<int> f(1), bad(1);
    auto cv = [](char c) { return c == 'A' ? 0 : c == 'C' ? 1 : c == 'G' ? 2 : 3; };
    string s;
    while (m--) {
        cin >> s;
        int u = 0;
        for (char c : s) {
