#include <bits/stdc++.h>
using namespace std;
const int inf = 1e9;
struct Seg {
    int n;
    vector<int> mx, mn, lz;
    Seg(vector<int>& a) : n(a.size() - 1), mx(4 * n), mn(4 * n), lz(4 * n) {
        function<void(int, int, int)> b = [&](int p, int l, int r) {
            if (l == r) {
                mx[p] = mn[p] = a[l];
                return;
            }
            int m = (l + r) / 2;
            b(p * 2, l, m);
            b(p * 2 + 1, m + 1, r);
            mx[p] = max(mx[p * 2], mx[p * 2 + 1]);
            mn[p] = min(mn[p * 2], mn[p * 2 + 1]);
        };
        b(1, 1, n);
    }
    void flip(int p) {
        int a = mx[p];
        mx[p] = -mn[p];
        mn[p] = -a;
        lz[p] ^= 1;
    }
    void push(int p) {
        if (lz[p]) flip(p * 2), flip(p * 2 + 1), lz[p] = 0;
    }
    void upd(int p, int l, int r, int L, int R) {
        if (L <= l && r <= R) {
            flip(p);
            return;
        }
        push(p);
        int m = (l + r) / 2;
        if (L <= m) upd(p * 2, l, m, L, R);
        if (R > m) upd(p * 2 + 1, m + 1, r, L, R);
        mx[p] = max(mx[p * 2], mx[p * 2 + 1]);
        mn[p] = min(mn[p * 2], mn[p * 2 + 1]);
    }
    void setv(int p, int l, int r, int x, int v) {
        if (l == r) {
            mx[p] = mn[p] = v;
            return;
        }
        push(p);
        int m = (l + r) / 2;
        x <= m ? setv(p * 2, l, m, x, v) : setv(p * 2 + 1, m + 1, r, x, v);
        mx[p] = max(mx[p * 2], mx[p * 2 + 1]);
        mn[p] = min(mn[p * 2], mn[p * 2 + 1]);
    }
    int qry(int p, int l, int r, int L, int R) {
        if (L <= l && r <= R) return mx[p];
        push(p);
        int m = (l + r) / 2, z = -inf;
        if (L <= m) z = max(z, qry(p * 2, l, m, L, R));
        if (R > m) z = max(z, qry(p * 2 + 1, m + 1, r, L, R));
        return z;
    }
};
int main() {
