        rec[c].push_back({c, 0, 0});
        bag[c].resize(1);
        int b = 0;
        for (auto [v, w] : g[c])
            if (!dead[v]) {
                bag[c].resize(++b + 1);
                col(v, c, w, c, b);
            }
        for (auto [v, w] : g[c])
            if (!dead[v]) dec(v);
    };
    dec(0);
    vector<multiset<ll>> tops(n);
    vector<ll> cand(n, neg);
    multiset<ll> global;
    auto calc = [&](int c) {
        if (tops[c].size() < 2) return neg;
        auto it = tops[c].end();
