            if (l >= r) return;
            int m = (l + r) / 2;
            nth_element(a.begin() + l, a.begin() + m, a.begin() + r,
                        [&](P& A, P& B) { return A.x[d] < B.x[d]; });
            build(l, m, d ^ 1);
            build(m + 1, r, d ^ 1);
