#include <bits/stdc++.h>
using namespace std;
using ll = long long;
struct P {
    array<int, 5> x;
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, K;
    while (cin >> n >> K) {
        vector<P> a(n);
        for (auto& z : a)
            for (int j = 0; j < K; j++) cin >> z.x[j];
        function<void(int, int, int)> build = [&](int l, int r, int d) {
            if (l >= r) return;
            int m = (l + r) / 2;
            nth_element(a.begin() + l, a.begin() + m, a.begin() + r,
                        [&](P& A, P& B) { return A.x[d] < B.x[d]; });
            build(l, m, (d + 1) % K);
            build(m + 1, r, (d + 1) % K);
        };
        build(0, n, 0);
        int T;
        cin >> T;
        while (T--) {
            P q;
            for (int j = 0; j < K; j++) cin >> q.x[j];
            int M;
            cin >> M;
            priority_queue<pair<ll, int>> pq;
            auto dist = [&](P& p) {
                ll s = 0;
                for (int j = 0; j < K; j++) {
                    ll d = q.x[j] - p.x[j];
                    s += d * d;
                }
                return s;
            };
            function<void(int, int, int)> ask = [&](int l, int r, int d) {
                if (l >= r) return;
                int m = (l + r) / 2;
                ll z = dist(a[m]);
                if ((int)pq.size() < M)
                    pq.push({z, m});
                else if (z < pq.top().first)
                    pq.pop(), pq.push({z, m});
                ll cut = (ll)q.x[d] - a[m].x[d];
                if (cut <= 0) {
                    ask(l, m, (d + 1) % K);
                    if ((int)pq.size() < M || cut * cut < pq.top().first)
                        ask(m + 1, r, (d + 1) % K);
                } else {
                    ask(m + 1, r, (d + 1) % K);
                    if ((int)pq.size() < M || cut * cut < pq.top().first) ask(l, m, (d + 1) % K);
                }
            };
            ask(0, n, 0);
            vector<int> ans;
            while (pq.size()) ans.push_back(pq.top().second), pq.pop();
            reverse(ans.begin(), ans.end());
            cout << "the closest " << M << " points are:\n";
            for (int id : ans) {
                for (int j = 0; j < K; j++) cout << a[id].x[j] << (j + 1 == K ? '\n' : ' ');
            }
        }
    }
}

