using namespace std;
struct LCT {
    vector<array<int, 2>> c;
    vector<int> f, v, s;
    vector<char> rv;
    LCT(int n) : c(n + 1), f(n + 1), v(n + 1), s(n + 1), rv(n + 1) {}
    bool root(int x) { return !f[x] || (c[f[x]][0] != x && c[f[x]][1] != x); }
    void pull(int x) { s[x] = s[c[x][0]] ^ s[c[x][1]] ^ v[x]; }
    void rev(int x) {
        if (x) swap(c[x][0], c[x][1]), rv[x] ^= 1;
    }
    void push(int x) {
        if (rv[x]) rev(c[x][0]), rev(c[x][1]), rv[x] = 0;
    }
    void rot(int x) {
        int y = f[x], z = f[y], k = c[y][1] == x, w = c[x][!k];
        if (!root(y)) c[z][c[z][1] == y] = x;
        f[x] = z;
        c[x][!k] = y;
        f[y] = x;
        c[y][k] = w;
        if (w) f[w] = y;
        pull(y);
        pull(x);
    }
    void splay(int x) {
        vector<int> a{x};
        for (int y = x; !root(y);) a.push_back(y = f[y]);
        while (a.size()) push(a.back()), a.pop_back();
        while (!root(x)) {
            int y = f[x], z = f[y];
            if (!root(y)) rot((c[y][1] == x) == (c[z][1] == y) ? y : x);
            rot(x);
        }
    }
    void access(int x) {
        for (int y = 0; x; x = f[y = x]) splay(x), c[x][1] = y, pull(x);
    }
    void makeroot(int x) {
        access(x);
        splay(x);
        rev(x);
    }
    int findroot(int x) {
        access(x);
        splay(x);
        push(x);
        while (c[x][0]) x = c[x][0], push(x);
        splay(x);
        return x;
    }
    void split(int x, int y) {
        makeroot(x);
        access(y);
        splay(y);
    }
};
int main() {
