    cin >> T;
    for (int cs = 1; cs <= T; cs++) {
        int n;
        cin >> n;
        vector<vector<int>> a(n + 1, vector<int>(n + 1));
        for (int i = 1; i <= n; i++)
            for (int j = 1; j <= n; j++) cin >> a[i][j];
        vector<N> tr(1);
        function<int(int, int, int, int)> build = [&](int x1, int x2, int y1, int y2) {
            int p = tr.size();
            tr.emplace_back();
            if (x1 == x2 && y1 == y2) {
                tr[p].a = tr[p].b = a[x1][y1];
                return p;
            }
            int xm = (x1 + x2) / 2, ym = (y1 + y2) / 2, z = 0;
            for (int xa : {x1, xm + 1})
                for (int ya : {y1, ym + 1}) {
