                    if (xa <= xb && ya <= yb) {
                        int q = build(xa, xb, ya, yb);
                        tr[p].ch[z++] = q;
                        tr[p].a = min(tr[p].a, tr[q].a);
                        tr[p].b = max(tr[p].b, tr[q].b);
