#include <bits/stdc++.h>
using namespace std;
using ll = long long;
struct N {
    int l = 0, r = 0;
    ll s = 0, z = 0;
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    while (cin >> n >> m) {
        vector<ll> a(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];
        vector<N> tr(1);
        function<int(int, int)> build = [&](int l, int r) {
            int p = tr.size();
            tr.emplace_back();
            if (l == r) {
                tr[p].s = a[l];
                return p;
            }
            int z = (l + r) / 2;
            tr[p].l = build(l, z);
            tr[p].r = build(z + 1, r);
            tr[p].s = tr[tr[p].l].s + tr[tr[p].r].s;
            return p;
        };
        vector<int> root(m + 2);
        root[0] = build(1, n);
        function<int(int, int, int, int, int, ll)> upd = [&](int o, int l, int r, int L, int R,
                                                             ll d) {
            int p = tr.size();
            tr.push_back(tr[o]);
            if (L <= l && r <= R) {
                tr[p].s += d * (r - l + 1);
                tr[p].z += d;
                return p;
            }
            int z = (l + r) / 2;
            if (L <= z) tr[p].l = upd(tr[o].l, l, z, L, R, d);
            if (R > z) tr[p].r = upd(tr[o].r, z + 1, r, L, R, d);
            tr[p].s = tr[tr[p].l].s + tr[tr[p].r].s + tr[p].z * (r - l + 1);
            return p;
        };
        function<ll(int, int, int, int, int, ll)> qry = [&](int p, int l, int r, int L, int R,
                                                            ll z) {
            if (L <= l && r <= R) return tr[p].s + z * (r - l + 1);
            z += tr[p].z;
            int m = (l + r) / 2;
            ll s = 0;
            if (L <= m) s += qry(tr[p].l, l, m, L, R, z);
            if (R > m) s += qry(tr[p].r, m + 1, r, L, R, z);
            return s;
        };
        int now = 0;
        while (m--) {
            char op;
            cin >> op;
            if (op == 'C') {
                int l, r;
                ll d;
                cin >> l >> r >> d;
                root[now + 1] = upd(root[now], 1, n, l, r, d);
                now++;
            } else if (op == 'B')
                cin >> now;
            else {
                int l, r, t = now;
                cin >> l >> r;
                if (op == 'H') cin >> t;
                cout << qry(root[t], 1, n, l, r, 0) << "\n";
            }
        }
    }
}

