    vector<vector<E>> g;
    vector<int> d, it;
    D(int n) : g(n), d(n), it(n) {}
    void add(int u, int v, int c) {
        E a{v, c, (int)g[v].size()}, b{u, 0, (int)g[u].size()};
        g[u].push_back(a);
        g[v].push_back(b);
    }
    int dfs(int u, int t, int f) {
        if (u == t) return f;
        for (int& i = it[u]; i < (int)g[u].size(); i++) {
            E& e = g[u][i];
            if (e.c && d[e.v] == d[u] + 1) {
                int z = dfs(e.v, t, min(f, e.c));
                if (z) {
                    e.c -= z;
                    g[e.v][e.r].c += z;
                    return z;
                }
            }
        }
        return 0;
    }
    int flow(int s, int t) {
        int F = 0, z;
        while (1) {
            fill(d.begin(), d.end(), -1);
            queue<int> q;
            q.push(s);
