#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    for (int cs = 1; cs <= T; cs++) {
        int n, M;
        cin >> n >> M;
        vector<ll> a(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];
        sort(a.begin() + 1, a.end());
        M = min(M, n);
        const ll inf = 4e18;
        vector<ll> pre(n + 1, inf), cur(n + 1, inf);
        pre[0] = 0;
        for (int g = 1; g <= M; g++) {
            fill(cur.begin(), cur.end(), inf);
            vector<int> q(n + 1);
            int h = 0, t = -1;
            auto X = [&](int j) { return a[j + 1]; };
            auto Y = [&](int j) { return pre[j] + X(j) * X(j); };
            auto val = [&](int j, ll x) { return Y(j) - 2 * X(j) * x; };
            for (int i = g; i <= n; i++) {
                int j = i - 1;
                if (pre[j] < inf) {
                    bool use = 1;
                    if (h <= t && X(q[t]) == X(j)) {
                        if (Y(q[t]) <= Y(j))
                            use = 0;
                        else
                            t--;
                    }
                    if (use) {
                        while (h < t && (Y(q[t]) - Y(q[t - 1])) * (X(j) - X(q[t])) >=
                                            (Y(j) - Y(q[t])) * (X(q[t]) - X(q[t - 1])))
                            t--;
                        q[++t] = j;
                    }
                }
                while (h < t && val(q[h + 1], a[i]) <= val(q[h], a[i])) h++;
                cur[i] = a[i] * a[i] + val(q[h], a[i]);
            }
            pre.swap(cur);
        }
        cout << "Case " << cs << ": " << pre[n] << "\n";
    }
}
